import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.DEy3KOfk.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","filePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","lastUpdated":1791412381000}'),n={name:"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md"};function i(o,e,d,l,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="the-client-disconnects-or-never-opens-a-session" tabindex="-1">The client disconnects or never opens a session <a class="header-anchor" href="#the-client-disconnects-or-never-opens-a-session" aria-label="Permalink to &quot;The client disconnects or never opens a session&quot;">​</a></h2><p>Confirm the client uses the supported Distant Horizons release in the generated <a href="./../README#compatibility-and-terrain">compatibility reference</a>. A protocol mismatch closes the session. Distant Horizons sessions are only opened by Java Edition players.</p><h2 id="requests-are-rejected-because-terrain-is-unavailable" tabindex="-1">Requests are rejected because terrain is unavailable <a class="header-anchor" href="#requests-are-rejected-because-terrain-is-unavailable" aria-label="Permalink to &quot;Requests are rejected because terrain is unavailable&quot;">​</a></h2><p>The plugin cannot load or generate chunks. It needs Pumpkin to have the requested area loaded, or a previous capture available in its cache. If the server reports that a chunk is not loaded, bring the area into range of a player or arrange for the server to load it before the request. The generated <a href="./../README#compatibility-and-terrain">terrain reference</a> describes the section size and capture requirements.</p><h2 id="a-client-sees-old-terrain" tabindex="-1">A client sees old terrain <a class="header-anchor" href="#a-client-sees-old-terrain" aria-label="Permalink to &quot;A client sees old terrain&quot;">​</a></h2><p>Cached captures are reused until they reach their configured refresh age and the server has the terrain loaded to rebuild them. Block placement and breaking invalidate affected captures. After replacing world data or changing a dimension&#39;s height, stop the server and remove this plugin&#39;s cache folder, then start the server again. The generated <a href="./../README#commands">Commands</a> reference also lists commands for clearing either cache tier or both.</p><h2 id="requests-stay-queued-or-progress-is-slow" tabindex="-1">Requests stay queued or progress is slow <a class="header-anchor" href="#requests-stay-queued-or-progress-is-slow" aria-label="Permalink to &quot;Requests stay queued or progress is slow&quot;">​</a></h2><p>Check the plugin&#39;s status command from the generated <a href="./../README#commands">Commands</a> reference. Its output includes pending requests and responses, logical queued response bytes retained, DH packet bytes sent, capture progress, completed and rejected requests, and the last rejection reason. <code>Chunk ... is not loaded</code> means terrain is unavailable to capture; <code>LOD request limit reached</code> means the bounded queue is full. Cached sections can still be delivered while a forced capture or sampling pause is active.</p><p>The client ETA includes time waiting since submission and does not measure network throughput. A nonzero client bandwidth limit applies to outgoing fragments; a fragment waits until its byte credit is available. The bucket burst is capped at one full DH fragment message; zero bandwidth is unlimited. Client configuration changes receive negotiated acknowledgements, with generation and sync settings handled independently. Review the current queue and transfer settings in the generated <a href="./../README#configuration">Configuration</a> reference. Those defaults remain provisional pending real-runtime measurements.</p>',10)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
